def metric(data: pd.DataFrame) -> float:
    def ttb_choice(row):
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        for i in range(len(a)):
            if a[i] > b[i]:
                return 0
            elif b[i] > a[i]:
                return 1
        return 0.5

    ttb_preds = [ttb_choice(row) for _, row in data.iterrows()]
    return float((data['response'] != ttb_preds).mean())

